  "myrdalshr.MYA.list.9.occupation": "Teacher",
  "myrdalshr.MYA.tagline": "Everyone’s list — a shared future in Mýrdal",
  "myrdalshr.MYZ.agenda.0.text": "Progress and innovation in the municipality.",
  "myrdalshr.MYZ.agenda.0.title": "Development",
  "myrdalshr.MYZ.agenda.1.text": "Environmental protection and climate action.",
  "myrdalshr.MYZ.agenda.1.title": "Environment",
  "myrdalshr.MYZ.agenda.2.text": "Community development and residents’ welfare.",
  "myrdalshr.MYZ.agenda.2.title": "Community",
  "myrdalshr.MYZ.list.1.bio": "Björn Þór Ólafsson is a store manager and former mayor of Mýrdalshreppur; he leads the Z-list of Samfélagið in the 2026 municipal elections.",
  "myrdalshr.MYZ.list.1.occupation": "Store Manager",
  "myrdalshr.MYZ.list.10.occupation": "Candidate",
