  "skeidagnup.SGE.list.5.occupation": "Farmer",
  "skeidagnup.SGE.list.6.occupation": "Farmer",
  "skeidagnup.SGE.list.7.occupation": "Teacher",
  "skeidagnup.SGE.list.8.occupation": "Tourism farmer and school bus driver",
